// ==================================================
// FILTER CURRENT WEEK
// Monday → Sunday
// ==================================================

const rows = $input.all();

// Get today's date
const today = new Date();

// Find Monday of the current week
const day = today.getDay(); // Sunday = 0
const diffToMonday = day === 0 ? -6 : 1 - day;

const weekStart = new Date(today);
weekStart.setDate(today.getDate() + diffToMonday);
weekStart.setHours(0, 0, 0, 0);

// Sunday = Monday + 6 days
const weekEnd = new Date(weekStart);
weekEnd.setDate(weekStart.getDate() + 6);
weekEnd.setHours(23, 59, 59, 999);

// Convert to YYYY-MM-DD
const formatDate = (date) => {
  return date.toISOString().split("T")[0];
};

const startDate = formatDate(weekStart);
const endDate = formatDate(weekEnd);

// Filter CRM records
const weeklyRecords = rows.filter(item => {

  const createdAt = String(item.json.created_at || "").trim();

  if (!createdAt) {
    return false;
  }

  return createdAt >= startDate && createdAt <= endDate;
});

// Return filtered records
return weeklyRecords;

const records = $input.all().map(item => item.json);

// ==================================================
// BASIC COUNTS
// ==================================================

const totalLeads = records.length;

const hotLeads = records.filter(
  r => String(r.lead_tier || "").toLowerCase() === "hot"
).length;

const warmLeads = records.filter(
  r => String(r.lead_tier || "").toLowerCase() === "warm"
).length;

const coldLeads = records.filter(
  r => String(r.lead_tier || "").toLowerCase() === "cold"
).length;

const unknownLeads = records.filter(
  r => String(r.lead_tier || "").toLowerCase() === "unknown"
).length;

// ==================================================
// PRODUCT COUNTS
// ==================================================

const productCounts = {};

for (const record of records) {

  const product = String(
    record.product_interest || "Unknown"
  ).trim();

  if (!productCounts[product]) {
    productCounts[product] = 0;
  }

  productCounts[product]++;
}

// Sort products by demand
const topProducts = Object.entries(productCounts)
  .map(([product, count]) => ({
    product,
    lead_count: count
  }))
  .sort((a, b) => b.lead_count - a.lead_count);

// ==================================================
// STATUS COUNTS
// ==================================================

const quotedLeads = records.filter(
  r => String(r.status || "").toLowerCase() === "quoted"
).length;

const openLeads = records.filter(
  r => String(r.status || "").toLowerCase() === "open"
).length;

const needsInfoLeads = records.filter(
  r => String(r.status || "").toLowerCase() === "needs info"
).length;

const inProgressLeads = records.filter(
  r => String(r.status || "").toLowerCase() === "in progress"
).length;

// ==================================================
// URGENCY COUNTS
// ==================================================

const highUrgency = records.filter(
  r => String(r.urgency || "").toLowerCase() === "high"
).length;

const mediumUrgency = records.filter(
  r => String(r.urgency || "").toLowerCase() === "medium"
).length;

const lowUrgency = records.filter(
  r => String(r.urgency || "").toLowerCase() === "low"
).length;

// ==================================================
// ASSIGNED REP COUNTS
// ==================================================

const repCounts = {};

for (const record of records) {

  const rep = String(
    record.assigned_to || "Unassigned"
  ).trim();

  if (!repCounts[rep]) {
    repCounts[rep] = 0;
  }

  repCounts[rep]++;
}

// ==================================================
// HIGH-VALUE OPPORTUNITIES
// ==================================================

// Only use explicitly provided numeric budgets.
// Do NOT infer revenue or sales.

const highValueOpportunities = records
  .filter(record => {
    const budget = Number(record.budget);
    return !isNaN(budget) && budget > 0;
  })
  .sort((a, b) => Number(b.budget) - Number(a.budget))
  .slice(0, 5)
  .map(record => ({
    lead_id: record.lead_id,
    customer_name: record.customer_name,
    product_interest: record.product_interest,
    budget: Number(record.budget),
    lead_tier: record.lead_tier,
    status: record.status
  }));

// ==================================================
// DATA QUALITY
// ==================================================

const recordsMissingEmail = records.filter(
  r => !r.email || String(r.email).trim() === ""
).length;

const recordsMissingProduct = records.filter(
  r =>
    !r.product_interest ||
    String(r.product_interest).trim() === "" ||
    String(r.product_interest).toLowerCase() === "unknown"
).length;

const recordsMissingBudget = records.filter(
  r =>
    !r.budget ||
    String(r.budget).trim() === "" ||
    String(r.budget).toLowerCase() === "unknown"
).length;

// ==================================================
// OUTPUT
// ==================================================

return [
  {
    json: {

      total_leads: totalLeads,

      lead_summary: {
        hot_leads: hotLeads,
        warm_leads: warmLeads,
        cold_leads: coldLeads,
        unknown_leads: unknownLeads
      },

      status_summary: {
        quoted: quotedLeads,
        open: openLeads,
        needs_info: needsInfoLeads,
        in_progress: inProgressLeads
      },

      urgency_summary: {
        high: highUrgency,
        medium: mediumUrgency,
        low: lowUrgency
      },

      top_products: topProducts,

      assigned_rep_summary: repCounts,

      high_value_opportunities: highValueOpportunities,

      data_quality: {
        records_missing_email: recordsMissingEmail,
        records_missing_product: recordsMissingProduct,
        records_missing_budget: recordsMissingBudget
      }
    }
  }
];

