// ============================================
// SALES GENIE - WEEKLY INSIGHTS
// DETERMINISTIC EVALUATION
// ============================================

// Get test case
const dataset = $('When fetching a dataset row').first().json;

// IMPORTANT:
// Use the actual node name from your workflow
const agentItem = $('Weekly Sales Insight Agent').first().json;


// ============================================
// HELPER: FIND DATASET FIELD
// Case-insensitive + trimmed
// ============================================

function getDatasetField(possibleNames) {
  const key = Object.keys(dataset).find(k =>
    possibleNames.includes(
      k.trim().toLowerCase()
    )
  );

  return key ? dataset[key] : undefined;
}


// ============================================
// PARSE AGENT OUTPUT
// ============================================

let actual;

try {

  actual =
    typeof agentItem.output === 'string'
      ? JSON.parse(agentItem.output)
      : agentItem.output;

} catch (error) {

  return [{
    json: {
      test_id:
        getDatasetField(['test_id', 'test id']) || 'UNKNOWN',

      aggregation_accuracy: 0,
      opportunity_accuracy: 0,
      format_compliance: 0,
      deterministic_score: 0,
      evaluation_status: 'FAIL',

      error:
        'Agent output is not valid JSON'
    }
  }];
}


// ============================================
// TEST ID
// ============================================

const testId =
  getDatasetField([
    'test_id',
    'test id'
  ]) || 'UNKNOWN';


// ============================================
// 1. AGGREGATION ACCURACY
// ============================================

const expected = {
  total_leads: Number(
    getDatasetField([
      'expected_total_leads',
      'expected total leads'
    ])
  ),

  hot_leads: Number(
    getDatasetField([
      'expected_hot_leads',
      'expected hot leads'
    ])
  ),

  warm_leads: Number(
    getDatasetField([
      'expected_warm_leads',
      'expected warm leads'
    ])
  ),

  cold_leads: Number(
    getDatasetField([
      'expected_cold_leads',
      'expected cold leads'
    ])
  ),

  unknown_leads: Number(
    getDatasetField([
      'expected_unknown_leads',
      'expected unknown leads'
    ])
  )
};


const leadSummary =
  actual.lead_summary || {};


const actualCounts = {

  total_leads:
    Number(leadSummary.total_leads),

  hot_leads:
    Number(leadSummary.hot_leads),

  warm_leads:
    Number(leadSummary.warm_leads),

  cold_leads:
    Number(leadSummary.cold_leads),

  unknown_leads:
    Number(leadSummary.unknown_leads)

};


const aggregationChecks = {};

for (const key of Object.keys(expected)) {

  aggregationChecks[key] =
    !Number.isNaN(expected[key]) &&
    expected[key] === actualCounts[key];

}


const aggregationPassed =
  Object.values(aggregationChecks)
    .filter(Boolean)
    .length;


const aggregationTotal =
  Object.keys(aggregationChecks).length;


const aggregationAccuracy =
  Math.round(
    (aggregationPassed / aggregationTotal) * 100
  );


// ============================================
// 2. HIGH-VALUE OPPORTUNITY ACCURACY
// Supports both:
// expected_high_value_opportunities
// expected_high_value_opportunity_ids
// ============================================

let expectedOpportunities = [];


// Try newer format first
const expectedOpportunityIdsField =
  getDatasetField([
    'expected_high_value_opportunity_ids',
    'expected high value opportunity ids'
  ]);


// --------------------------------------------
// NEW FORMAT
// L001,L005,L009
// --------------------------------------------

if (
  typeof expectedOpportunityIdsField === 'string' &&
  expectedOpportunityIdsField.trim() !== ''
) {

  expectedOpportunities =
    expectedOpportunityIdsField
      .split(',')
      .map(id => ({
        lead_id: id.trim()
      }))
      .filter(item => item.lead_id !== '');

}


// --------------------------------------------
// OLD FORMAT
// [{"lead_id":"L001"},{"lead_id":"L005"}]
// --------------------------------------------

else {

  const opportunityField =
    getDatasetField([
      'expected_high_value_opportunities',
      'expected high value opportunities'
    ]);

  if (Array.isArray(opportunityField)) {

    expectedOpportunities =
      opportunityField;

  }

  else if (
    typeof opportunityField === 'string' &&
    opportunityField.trim() !== ''
  ) {

    try {

      expectedOpportunities =
        JSON.parse(opportunityField);

    }

    catch (error) {

      try {

        const cleaned =
          opportunityField
            .trim()
            .replace(/^"+|"+$/g, '')
            .replace(/""/g, '"');

        expectedOpportunities =
          JSON.parse(cleaned);

      }

      catch (secondError) {

        expectedOpportunities = [];

      }

    }

  }

}


if (!Array.isArray(expectedOpportunities)) {

  expectedOpportunities = [];

}


const actualOpportunities =
  Array.isArray(
    actual.high_value_opportunities
  )
    ? actual.high_value_opportunities
    : [];


// Expected IDs
const expectedIds =
  expectedOpportunities
    .map(item =>
      typeof item === 'string'
        ? item
        : item.lead_id
    )
    .map(id =>
      String(id || '').trim()
    )
    .filter(Boolean)
    .sort();


// Actual IDs
const actualIds =
  actualOpportunities
    .map(item =>
      String(item.lead_id || '').trim()
    )
    .filter(Boolean)
    .sort();


const opportunityAccuracy =
  JSON.stringify(expectedIds) ===
  JSON.stringify(actualIds)
    ? 100
    : 0;


// ============================================
// 3. FORMAT COMPLIANCE
// ============================================

const requiredFields = [

  'executive_summary',

  'lead_summary',

  'top_products',

  'key_trends',

  'high_value_opportunities',

  'follow_up_priorities',

  'recommended_actions',

  'data_quality_notes'

];


const formatChecks = {};


for (const field of requiredFields) {

  formatChecks[field] =
    Object.prototype.hasOwnProperty.call(
      actual,
      field
    );

}


const formatPassed =
  Object.values(formatChecks)
    .filter(Boolean)
    .length;


const formatTotal =
  requiredFields.length;


const formatCompliance =
  Math.round(
    (formatPassed / formatTotal) * 100
  );


// ============================================
// 4. FINAL DETERMINISTIC SCORE
// ============================================

const deterministicScore =
  Math.round(

    aggregationAccuracy * 0.60 +

    opportunityAccuracy * 0.25 +

    formatCompliance * 0.15

  );


const evaluationStatus =
  deterministicScore >= 80
    ? 'PASS'
    : 'FAIL';


// ============================================
// FINAL OUTPUT
// ============================================

return [{
  json: {

    test_id:
      testId,

    aggregation_accuracy:
      aggregationAccuracy,

    aggregation_checks:
      aggregationChecks,

    opportunity_accuracy:
      opportunityAccuracy,

    expected_opportunity_ids:
      expectedIds,

    actual_opportunity_ids:
      actualIds,

    format_compliance:
      formatCompliance,

    format_checks:
      formatChecks,

    deterministic_score:
      deterministicScore,

    evaluation_status:
      evaluationStatus

  }
}];
